/**
 * scripts/data/emit.ts
 *
 * Helpers for writing generated TypeScript modules under `src/common/data/generated/`.
 * Those files are excluded from Biome; keep numeric arrays compact here.
 */

import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

/** Formats a number array as a single compact literal. */
export function numberArray(values: readonly number[]): string {
  return `[${values.join(",")}]`;
}

/**
 * Writes a generated module with the standard "do not edit" banner.
 *
 * @param relativePath - path relative to the repository root
 * @param description - one-paragraph description of the module's contents
 * @param body - module source without the banner
 */
export function writeGeneratedModule(relativePath: string, description: string, body: string): void {
  const path = resolve(process.cwd(), relativePath);
  const banner = `// Generated by npm run build-data — do not edit.
/**
 * ${relativePath.split("/").pop()}
 *
 * GENERATED FILE — DO NOT EDIT BY HAND.
 * Regenerate with \`npm run build-data\` (see scripts/build-data.ts).
 *
${description
  .trim()
  .split("\n")
  .map((line) => ` * ${line}`.trimEnd())
  .join("\n")}
 */
`;
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, `${banner}\n${body.trimEnd()}\n`, "utf8");
  console.log(`  wrote ${relativePath}`);
}
